g=hou.node('/obj/girl')
fingers=[('index',0),('middle',1),('ring',2),('little',3)]
# offsets relative to F150 value; curl peaks ~F172, releases by F190
shape=[(160,4.0),(172,10.0),(186,3.0)]
def key(p,f,v):
    kf=hou.Keyframe(); kf.setFrame(f); kf.setValue(v); kf.setExpression('ease()'); p.setKeyframe(kf)
for name,lag in fingers:
